6"><input class="form-control" name="description" placeholder="Serviço ou item manual"></div><div class="col-md-2"><input class="form-control" name="quantity" value="1" placeholder="Qtd"></div><div class="col-md-2"><input class="form-control" name="unit_price" placeholder="Valor"></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100">Adicionar manual</button></div></form></div><div class="col-lg-5"><form class="row g-1" method="post" action="/sports/commands/<?=(int)$cmd['id']?>/close"><?=CSRF::field()?><div class="col-6"><input class="form-control" name="discount" value="0" placeholder="Desconto"></div><div class="col-6"><input class="form-control" name="surcharge" value="0" placeholder="Acréscimo"></div><div class="col-8"><select class="form-select" name="payment_method"><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="credito">Crédito</option><option value="debito">Débito</option><option value="transferencia">Transferência</option><option value="outro">Outro</option></select></div><div class="col-4"><button class="btn btn-success w-100">Fechar</button></div></form></div></div><?php endif;?></div></article><?php endforeach;?><?php if(!$commands):?><div class="sports-empty">Nenhuma comanda.</div><?php endif;?></div></div>
